import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.ArrayDeque
import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val tokenizer = StringTokenizer(br.readLine()!!)
    val n = tokenizer.nextToken().toInt()
    val m = tokenizer.nextToken().toInt()

    val types = IntArray(n)
    val typeTokenizer = StringTokenizer(br.readLine()!!)
    for (i in 0 until n) {
        types[i] = typeTokenizer.nextToken().toInt()
    }

    val adj = Array(n) { mutableListOf<Int>() }
    val adjr = Array(n) { mutableListOf<Int>() }

    for (i in 0 until m) {
        val edgeTokenizer = StringTokenizer(br.readLine()!!)
        val u = edgeTokenizer.nextToken().toInt() - 1
        val v = edgeTokenizer.nextToken().toInt() - 1
        adj[u].add(v)
        adjr[v].add(u)
    }

    val mark = BooleanArray(n)
    val ans = IntArray(n)
    val stack = ArrayDeque<Int>()

    // DFS1: forward from type 1
    for (i in 0 until n) {
        if (!mark[i] && types[i] == 1) {
            stack.clear()
            stack.push(i)
            while (stack.isNotEmpty()) {
                val x = stack.pop()
                if (mark[x]) continue
                mark[x] = true
                ans[x]++
                for (u in adj[x]) {
                    if (!mark[u]) stack.push(u)
                }
            }
        }
    }

    // Reset mark
    for (i in 0 until n) mark[i] = false

    // DFS2: reverse from type 2
    for (i in 0 until n) {
        if (!mark[i] && types[i] == 2) {
            stack.clear()
            stack.push(i)
            while (stack.isNotEmpty()) {
                val x = stack.pop()
                if (mark[x]) continue
                mark[x] = true
                ans[x]++
                if (types[x] == 1) continue
                for (u in adjr[x]) {
                    if (!mark[u]) stack.push(u)
                }
            }
        }
    }

    val sb = StringBuilder()
    for (i in 0 until n) {
        sb.append(if (ans[i] == 2) 1 else 0).append('\n')
    }
    print(sb)
}

